export function clsx() {
	var i=0, tmp, str='', len=arguments.length;
	for (; i < len; i++) {
		if (tmp = arguments[i]) {
			if (typeof tmp === 'string') {
				str += (str && ' ') + tmp;
			}
		}
	}
	return str;
}

export default clsx;

const { Suite } = require('benchmark');
const classnames = require('classnames');
const classcat = require('classcat');
const clsx = require('../dist/clsx');
const old = require('clsx');
const lite = require('../dist/lite');

function bench(name, ...args) {
	console.log(`\n# ${name}`);
	new Suite()
		.add('classcat ≠  ', () => classcat.apply(classcat, [args]))
		.add('classnames  ', () => classnames.apply(classnames, args))
		.add('clsx (prev) ', () => old.apply(old, args))
		.add('clsx        ', () => clsx.apply(clsx, args))
		.add('clsx (lite) ', () => lite.apply(lite, args))
		.on('cycle', e => console.log('  ' + e.target))
		.run();
}

bench(
	'Strings',
	'foo', '', 'bar', 'baz', 'bax', 'bux'
);

bench(
	'Objects',
	{ foo:true, bar:true, bax:true, bux:false },
	{ baz:true, bax:false, bux:true }
);

bench(
	'Arrays',
	['foo', 'bar'],
	['baz', 'bax', 'bux']
);

bench(
	'Nested Arrays',
	['foo', ['bar']],
	['baz', ['bax', ['bux']]]
);

bench(
	'Nested Arrays w/ Objects',
	['foo', { bar:true, bax:true, bux:false }],
	['bax', { bax:false, bux:true }]
);

bench(
	'Mixed',
	'foo', 'bar',
	{ bax:true, bux:false },
	['baz', { bax:false, bux:true }]
);

bench(
	'Mixed (Bad Data)',
	'foo', 'bar',
	undefined, null, NaN,
	() => {},
	{ bax:true, bux:false, 123:true },
	['baz', { bax:false, bux:true, abc:null }, {}]
);

// @ts-check
const fs = require('fs');
const zlib = require('zlib');
const { minify } = require('terser');
const pkg = require('../package.json');

/**
 * @param {string} file
 * @param {string} source
 */
function write(file, source) {
	let isModule = !source.startsWith('!function');
	let result = minify(source, {
		module: isModule,
		compress: true,
	});

	if (result.code) {
		fs.writeFileSync(file, result.code);
		let size = zlib.gzipSync(result.code).byteLength;
		console.log('~> "%s" (%d b)', file, size);
	} else {
		console.error('!! "%s" ::', file, result.error);
	}
}

/**
 * @typedef Export
 * @property {Condition} import
 * @property {Condition} default
 */

/**
 * @typedef Condition
 * @property {string} types
 * @property {string} default
 */

/**
 * @param {string} file
 * @param {"." | "./lite"} entry
 */
function bundle(file, entry) {
	fs.existsSync('dist') || fs.mkdirSync('dist');

	/**
	 * @type {Export}
	 */
	let output = pkg.exports[entry];
	let input = fs.readFileSync(file, 'utf8');

	// copy for ESM file
	write(output.import.default, input);

	// transform ESM -> CJS exports
	write(output.default.default, input.replace('export function', 'function').replace(
		'export default clsx;',
		'module.exports = clsx;\n'
		+ 'module.exports.clsx = clsx;'
	));

	if (entry === '.') {
		// transform ESM -> UMD exports
		input = input.replace('export function', 'function').replace('export default clsx;', 'return clsx.clsx=clsx, clsx;');
		write(pkg.unpkg, '!function(global,factory){"object"==typeof exports&&"undefined"!=typeof module?module.exports=factory():"function"==typeof define&&define.amd?define(factory):global.clsx=factory()}(this,function(){' + input + '});');
	}
}

bundle('src/index.js', '.');
console.log('---');
bundle('src/lite.js', './lite');

function toVal(mix) {
	var k, y, str='';

	if (typeof mix === 'string' || typeof mix === 'number') {
		str += mix;
	} else if (typeof mix === 'object') {
		if (Array.isArray(mix)) {
			var len=mix.length;
			for (k=0; k < len; k++) {
				if (mix[k]) {
					if (y = toVal(mix[k])) {
						str && (str += ' ');
						str += y;
					}
				}
			}
		} else {
			for (y in mix) {
				if (mix[y]) {
					str && (str += ' ');
					str += y;
				}
			}
		}
	}

	return str;
}

export function clsx() {
	var i=0, tmp, x, str='', len=arguments.length;
	for (; i < len; i++) {
		if (tmp = arguments[i]) {
			if (x = toVal(tmp)) {
				str && (str += ' ');
				str += x
			}
		}
	}
	return str;
}

export default clsx;

/**
 * Ported from `classnames` for compatibility checks.
 */

import { test } from 'uvu';
import * as assert from 'uvu/assert';
import clsx from '../src';

test('(compat) keeps object keys with truthy values', () => {
	const out = clsx({ a:true, b:false, c:0, d:null, e:undefined, f:1 });
	assert.is(out, 'a f');
});

test('(compat) joins arrays of class names and ignore falsy values', () => {
	const out = clsx('a', 0, null, undefined, true, 1, 'b');
	assert.is(out, 'a 1 b');
});

test('(compat) supports heterogenous arguments', () => {
	assert.is(clsx({ a:true }, 'b', 0), 'a b');
});

test('(compat) should be trimmed', () => {
	assert.is(clsx('', 'b', {}, ''), 'b');
});

test('(compat) returns an empty string for an empty configuration', () => {
	assert.is(clsx({}), '');
});

test('(compat) supports an array of class names', () => {
	assert.is(clsx(['a', 'b']), 'a b');
});

test('(compat) joins array arguments with string arguments', () => {
	assert.is(clsx(['a', 'b'], 'c'), 'a b c');
	assert.is(clsx('c', ['a', 'b']), 'c a b');
});

test('(compat) handles multiple array arguments', () => {
	assert.is(clsx(['a', 'b'], ['c', 'd']), 'a b c d');
});

test('(compat) handles arrays that include falsy and true values', () => {
	assert.is(clsx(['a', 0, null, undefined, false, true, 'b']), 'a b');
});

test('(compat) handles arrays that include arrays', () => {
	assert.is(clsx(['a', ['b', 'c']]), 'a b c');
});

test('(compat) handles arrays that include objects', () => {
	assert.is(clsx(['a', { b:true, c:false }]), 'a b');
});

test('(compat) handles deep array recursion', () => {
	assert.is(clsx(['a', ['b', ['c', { d:true }]]]), 'a b c d');
});

test('(compat) handles arrays that are empty', () => {
	assert.is(clsx('a', []), 'a');
});

test('(compat) handles nested arrays that have empty nested arrays', () => {
	assert.is(clsx('a', [[]]), 'a');
});

test('(compat) handles all types of truthy and falsy property values as expected', () => {
	const out = clsx({
		// falsy:
		null: null,
		emptyString: '',
		noNumber: NaN,
		zero: 0,
		negativeZero: -0,
		false: false,
		undefined: undefined,

		// truthy (literally anything else):
		nonEmptyString: 'foobar',
		whitespace: ' ',
		function: Object.prototype.toString,
		emptyObject: {},
		nonEmptyObject: {a: 1, b: 2},
		emptyList: [],
		nonEmptyList: [1, 2, 3],
		greaterZero: 1
	});

	assert.is(out, 'nonEmptyString whitespace function emptyObject nonEmptyObject emptyList nonEmptyList greaterZero');
});

test.run();

// @ts-check
import { test } from 'uvu';
import * as assert from 'uvu/assert';
import * as mod from '../src';

const fn = mod.default;

test('exports', () => {
	assert.type(mod.default, 'function', 'exports default function');
	assert.type(mod.clsx, 'function', 'exports named function');
	assert.is(mod.default, mod.clsx, 'exports are equal');

	assert.type(mod.default(), 'string', '~> returns string output');
	assert.type(mod.clsx(), 'string', '~> returns string output');
});

test('strings', () => {
	assert.is(fn(''), '');
	assert.is(fn('foo'), 'foo');
	assert.is(fn(true && 'foo'), 'foo');
	assert.is(fn(false && 'foo'), '');
});

test('strings (variadic)', () => {
	assert.is(fn(''), '');
	assert.is(fn('foo', 'bar'), 'foo bar');
	assert.is(fn(true && 'foo', false && 'bar', 'baz'), 'foo baz');
	assert.is(fn(false && 'foo', 'bar', 'baz', ''), 'bar baz');
});

test('numbers', () => {
	assert.is(fn(1), '1');
	assert.is(fn(12), '12');
	assert.is(fn(0.1), '0.1');
	assert.is(fn(0), '');

	assert.is(fn(Infinity), 'Infinity');
	assert.is(fn(NaN), '');
});

test('numbers (variadic)', () => {
	assert.is(fn(0, 1), '1');
	assert.is(fn(1, 2), '1 2');
});

test('objects', () => {
	assert.is(fn({}), '');
	assert.is(fn({ foo:true }), 'foo');
	assert.is(fn({ foo:true, bar:false }), 'foo');
	assert.is(fn({ foo:'hiya', bar:1 }), 'foo bar');
	assert.is(fn({ foo:1, bar:0, baz:1 }), 'foo baz');
	assert.is(fn({ '-foo':1, '--bar':1 }), '-foo --bar');
});

test('objects (variadic)', () => {
	assert.is(fn({}, {}), '');
	assert.is(fn({ foo:1 }, { bar:2 }), 'foo bar');
	assert.is(fn({ foo:1 }, null, { baz:1, bat:0 }), 'foo baz');
	assert.is(fn({ foo:1 }, {}, {}, { bar:'a' }, { baz:null, bat:Infinity }), 'foo bar bat');
});

test('arrays', () => {
	assert.is(fn([]), '');
	assert.is(fn(['foo']), 'foo');
	assert.is(fn(['foo', 'bar']), 'foo bar');
	assert.is(fn(['foo', 0 && 'bar', 1 && 'baz']), 'foo baz');
});

test('arrays (nested)', () => {
	assert.is(fn([[[]]]), '');
	assert.is(fn([[['foo']]]), 'foo');
	assert.is(fn([true, [['foo']]]), 'foo');;
	assert.is(fn(['foo', ['bar', ['', [['baz']]]]]), 'foo bar baz');
});

test('arrays (variadic)', () => {
	assert.is(fn([], []), '');
	assert.is(fn(['foo'], ['bar']), 'foo bar');
	assert.is(fn(['foo'], null, ['baz', ''], true, '', []), 'foo baz');
});

test('arrays (no `push` escape)', () => {
	assert.is(fn({ push:1 }), 'push');
	assert.is(fn({ pop:true }), 'pop');
	assert.is(fn({ push:true }), 'push');
	assert.is(fn('hello', { world:1, push:true }), 'hello world push');
});

test('functions', () => {
	const foo = () => {};
	assert.is(fn(foo, 'hello'), 'hello');
	assert.is(fn(foo, 'hello', fn), 'hello');
	assert.is(fn(foo, 'hello', [[fn], 'world']), 'hello world');
});

test.run();

// @ts-check
import { test } from 'uvu';
import * as assert from 'uvu/assert';
import * as mod from '../src/lite';

const fn = mod.default;

test('exports', () => {
	assert.type(mod.default, 'function', 'exports default function');
	assert.type(mod.clsx, 'function', 'exports named function');
	assert.is(mod.default, mod.clsx, 'exports are equal');

	assert.type(mod.default(), 'string', '~> returns string output');
	assert.type(mod.clsx(), 'string', '~> returns string output');
});

test('strings', () => {
	assert.is(fn(''), '');
	assert.is(fn('foo'), 'foo');
	assert.is(fn(true && 'foo'), 'foo');
	assert.is(fn(false && 'foo'), '');
});

test('strings (variadic)', () => {
	assert.is(fn(''), '');
	assert.is(fn('foo', 'bar'), 'foo bar');
	assert.is(fn(true && 'foo', false && 'bar', 'baz'), 'foo baz');
	assert.is(fn(false && 'foo', 'bar', 'baz', ''), 'bar baz');
});

test('emptys', () => {
	assert.is(fn(''), '');
	assert.is(fn(undefined), '');
	assert.is(fn(null), '');
	assert.is(fn(0), '');
});

// lite ignores all non-strings
test('non-strings', () => {
	// number
	assert.is(fn(1), '');
	assert.is(fn(1, 2), '');
	assert.is(fn(Infinity), '');
	assert.is(fn(NaN), '');
	assert.is(fn(0), '');

	// objects
	assert.is(fn({}), '');
	assert.is(fn(null), '');
	assert.is(fn({ a:1 }), '');
	assert.is(fn({ a:1 }, { b:2 }), '');

	// arrays
	assert.is(fn([]), '');
	assert.is(fn(['foo']), '');
	assert.is(fn(['foo', 'bar']), '');

	// functions
	assert.is(fn(fn), '');
	assert.is(fn(fn, fn), '');
});

test.run();

