describe("path-to-regexp", () => {
  describe("PathError", () => {
    it("should contain original path and debug url", () => {
      const error = new PathError(
        "Unexpected end at index 7, expected }",
        "/{:foo,",
      );

      expect(error).toBeInstanceOf(TypeError);
      expect(error.message).toBe(
        "Unexpected end at index 7, expected }: /{:foo,; visit https://git.new/pathToRegexpError for info",
      );
      expect(error.originalPath).toBe("/{:foo,");
    });

    it("should omit original url when undefined", () => {
      const error = new PathError(
        "Unexpected end at index 7, expected }",
        undefined,
      );

      expect(error).toBeInstanceOf(TypeError);
      expect(error.message).toBe(
        "Unexpected end at index 7, expected }; visit https://git.new/pathToRegexpError for info",
      );
      expect(error.originalPath).toBeUndefined();
    });
  });

  describe("parse errors", () => {
    it.each(["/{", "/{:foo,", "/{:foo/{x,y}"])(
      "should throw on unbalanced group: %s",
      (path) => {
        expect(() => parse(path)).toThrow(
          new PathError(
            `Unexpected end at index ${path.length}, expected }`,
            path,
          ),
        );
      },
    );

    it("should throw on missing param name", () => {
      expect(() => parse("/:/")).toThrow(
        new PathError("Missing parameter name at index 2", "/:/"),
      );
    });

    it("should throw on missing wildcard name", () => {
      expect(() => parse("/*/")).toThrow(
        new PathError("Missing parameter name at index 2", "/*/"),
      );
    });

    it("should throw on unterminated quote", () => {
      expect(() => parse('/:"foo')).toThrow(
        new PathError("Unterminated quote at index 2", '/:"foo'),
      );
    });

    it("should throw on eol backslash", () => {
      expect(() => parse("/foo\\")).toThrow(
        new PathError("Unexpected end after \\ at index 5", "/foo\\"),
      );
    });

    it("should throw on eol backslash in group", () => {
      expect(() => parse("/foo/{bar\\")).toThrow(
        new PathError("Unexpected end after \\ at index 10", "/foo/{bar\\"),
      );
    });

    it("should throw on eol backslash after param", () => {
      expect(() => parse("/foo/:bar\\")).toThrow(
        new PathError("Unexpected end after \\ at index 10", "/foo/:bar\\"),
      );
    });

    it("should throw on eol backslash after wildcard", () => {
      expect(() => parse("/foo/*bar\\")).toThrow(
        new PathError("Unexpected end after \\ at index 10", "/foo/*bar\\"),
      );
    });

    it("should throw on eol backslash in quoted param", () => {
      expect(() => parse('/foo/:"bar\\')).toThrow(
        new PathError("Unterminated quote at index 6", '/foo/:"bar\\'),
      );
    });

    it.each(["}", "(", ")", "[", "]", "+", "?", "!"])(
      "should throw on unexpected character %s",
      (char) => {
        expect(() => parse(`/foo/${char}`)).toThrow(
          new PathError(`Unexpected ${char} at index 5`, `/foo/${char}`),
        );
      },
    );
  });

