      ).toThrow(new PathError('Missing text before "b" param', undefined));
    });

    it("should throw with `originalPath` when missing text between params using TokenData", () => {
      expect(() =>
        pathToRegexp(
          new TokenData(
            [
              { type: "param", name: "a" },
              { type: "param", name: "b" },
            ],
            "/[a][b]",
          ),
        ),
      ).toThrow(new PathError('Missing text before "b" param', "/[a][b]"));
    });

    it("should contain the error line", () => {
      expect.hasAssertions();

      try {
        pathToRegexp("/:");
      } catch (error) {
        const stack = (error as Error).stack
          ?.split("\n")
          .slice(0, 6)
          .join("\n");
        expect(stack).toContain("index.spec.ts");
      }
    });

    it("should throw when too many alternative routes are generated", () => {
      const segments = new Array(10).fill("{/x}").join("");

      expect(() => pathToRegexp(segments)).toThrow(
        new PathError("Too many path combinations", segments),
      );
    });
  });

  describe("stringify errors", () => {
    it("should error on unknown token", () => {
      expect(() =>
        stringify({ tokens: [{ type: "unknown", value: "test" } as any] }),
      ).toThrow(new TypeError("Unknown token type: unknown"));
    });
  });

  describe.each(PARSER_TESTS)(
    "parse $path with $options",
    ({ path, options, expected }) => {
      it("should parse the path", () => {
        const data = parse(path, options);
        expect(data).toEqual(expected);
      });
    },
  );

  describe.each(STRINGIFY_TESTS)(
    "stringify $tokens with $options",
    ({ data, expected }) => {
      it("should stringify the path", () => {
        const path = stringify(data);
        expect(path).toEqual(expected);
      });
    },
  );

  describe.each(["param", "wildcard"] as const)(
    "stringify %s followed by empty text",
    (type) => {
      it.each([
        ["bar", '"foo"bar'],
        ["\u{1D6FC}", '"foo"\u{1D6FC}'],
        ["/bar", "foo/bar"],
        ["", "foo"],
      ])("should preserve the name before %j", (suffix, expected) => {
        const data = new TokenData([
          { type: "text", value: "/" },
          { type, name: "foo" },
          { type: "text", value: "" },
          { type: "text", value: "" },
          { type: "text", value: suffix },
        ]);
        const path = stringify(data);
        const params = { foo: type === "param" ? "value" : ["value", "more"] };

        expect(path).toBe(`/${type === "param" ? ":" : "*"}${expected}`);
        expect(compile(path)(params)).toBe(compile(data)(params));
      });
    },
  );

  describe.each(COMPILE_TESTS)(
